11	func mustOK(t *testing.T, store *MetricStore, line string) *BatchResult {
12		t.Helper()
13		res, err := store.IngestLine(line)
14		if err != nil {
15			t.Fatalf("expected success for %s, got error: %+v", line, err)
16		}
17		return res
18	}
