29	func TestIngestBasicSuccessAndSnapshot(t *testing.T) {
30		store := NewMetricStore()
31		res := mustOK(t, store, `[
32			{"name":"cpu","timestamp":2000,"value":0.5,"labels":{"host":"b"}},
33			{"name":"cpu","timestamp":1000,"value":0.25,"labels":{"host":"a"}},
34			{"name":"mem","timestamp":1000,"value":1}
35		]`)
36		if res.Added != 3 || res.Duplicates != 0 {
37			t.Fatalf("counts = %d/%d, want 3/0", res.Added, res.Duplicates)
38		}
39		if len(res.Series) != 3 {
40			t.Fatalf("series len = %d, want 3", len(res.Series))
41		}
42		// 序列排序：mem 排在最后；同指标名按标签键值对字典序 host=a 在 host=b 前。
43		if res.Series[0].Name != "cpu" || res.Series[0].Labels["host"] != "a" {
44			t.Fatalf("series[0] = %+v, want cpu host=a", res.Series[0])
45		}
46		if res.Series[1].Labels["host"] != "b" {
47			t.Fatalf("series[1] = %+v, want cpu host=b", res.Series[1])
48		}
49		if res.Series[2].Name != "mem" {
50			t.Fatalf("series[2] = %+v, want mem", res.Series[2])
51		}
52		// 序列内按时间戳升序（输入故意乱序）。
53		if pts := res.Series[0].Points; len(pts) != 1 || pts[0].Timestamp != 1000 {
