91	func TestCrossBatchDuplicateAndConflict(t *testing.T) {
92		store := NewMetricStore()
93		mustOK(t, store, `[{"name":"m","timestamp":1,"value":1}]`)
94	
95		// 完全相同（1 与 1.0）→ 跨批重复。
