377			aBefore.Points[1] != (Point{Timestamp: 2000, Value: 4}) {
378			t.Fatalf("retained snapshot changed after new write: %+v", snapBefore.Series)
379		}
380		bBefore := snapBefore.Series[findViewIndex(t, snapBefore, "cpu", map[string]string{"host": "b"})]
381		if len(bBefore.Points) != 1 || bBefore.Points[0] != (Point{Timestamp: 1000, Value: 8}) {
382			t.Fatalf("retained host=b snapshot changed: %+v", bBefore)
383		}
384	
385		// 先前保留的查询结果也不跟着变化。
386		if len(qBefore.Series) != 1 || qBefore.Series[0].Count != 2 || qBefore.Series[0].Average != 3 {
387			t.Fatalf("retained host=a query changed: %+v", qBefore.Series)
388		}
389		if len(qAllBefore.Series) != 2 {
390			t.Fatalf("retained full query gained the new point: %+v", qAllBefore.Series)
391		}
